/* Anonymous revision: no accounts, local storage, score queue or private API requests. */
(()=>{
 const topic=document.querySelector('#offlineTopic'),work=document.querySelector('#offlineWork'),feedback=document.querySelector('#offlineFeedback'),next=document.querySelector('#offlineNext');
 let bank=null,word=null,previous=null;
 const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function draw(){
  const pool=bank[topic.value];const choices=pool.filter(w=>w[0]!==previous);word=(choices.length?choices:pool)[Math.floor(Math.random()*(choices.length||pool.length))];previous=word[0];
  const options=[word,...pool.filter(w=>w[0]!==word[0]).sort(()=>Math.random()-.5).slice(0,3)].sort(()=>Math.random()-.5);
  feedback.textContent='';next.hidden=true;
  work.innerHTML='<p class="offlinePicture" aria-hidden="true">'+escape(word[2]||'📚')+'</p><p class="offlineHint">Come si dice in inglese?</p><p class="offlinePrompt">'+escape(word[1])+'</p><button id="offlineAudio" type="button">🔊 Ascolta</button><div class="offlineOptions">'+options.map((w,i)=>'<button type="button" data-option="'+i+'">'+escape(w[0])+'</button>').join('')+'</div>';
  work.querySelectorAll('[data-option]').forEach(button=>button.onclick=()=>{
   if(options[Number(button.dataset.option)][0]===word[0]){button.classList.add('correct');window.wordylandLearning.show(feedback,true,{expected:word[0],word:word[0],translation:word[1],button});next.hidden=false;work.querySelectorAll('[data-option]').forEach(b=>b.disabled=true);next.focus({preventScroll:true});}
   else{button.disabled=true;window.wordylandLearning.show(feedback,false,{expected:word[0],word:word[0],answer:options[Number(button.dataset.option)][0],chosenTranslation:options[Number(button.dataset.option)][1],translation:word[1],kind:'choice',button});}
  });
  work.querySelector('#offlineAudio').onclick=()=>{
   if(!('speechSynthesis'in window)){feedback.textContent='La voce non è disponibile. Puoi leggere le parole e continuare.';return;}
   speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(word[0]);utterance.lang='en-GB';utterance.rate=.8;utterance.onerror=()=>{feedback.textContent='La voce non è disponibile offline. Puoi continuare leggendo.';};speechSynthesis.speak(utterance);
  };
 }
 topic.onchange=()=>{if(bank){if('speechSynthesis'in window)speechSynthesis.cancel();draw();}};next.onclick=draw;
 fetch('curriculum.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{bank=data;draw();}).catch(()=>{work.textContent='Il ripasso non è ancora scaricato. Apri WordyLand con Internet almeno una volta, poi riprova.';topic.disabled=true;});
})();

/* Standalone guest spelling: public content only; no account API or sync queue. */
(()=>{
 const panel=document.querySelector('#offlineFoundation'),host=document.querySelector('#offlineFoundationWork'),status=document.querySelector('#offlineFoundationStatus'),revision=document.querySelector('#offlineRevision'),open=document.querySelector('#offlineFoundationOpen'),back=document.querySelector('#offlineRevisionOpen');
 const key='wordylandOfflineTrainingV1',esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let content=null,state=null,current=null,locked=false,loading=false,speechGeneration=0;
 const fresh=()=>({version:1,counts:{},sessions:{},completed:0});
 const clone=()=>JSON.parse(JSON.stringify(state));
 const selectedVoice=()=>('speechSynthesis'in window?speechSynthesis.getVoices().find(v=>v.localService===true&&v.lang.toLowerCase().startsWith('en')):null);
 function stop(){speechGeneration++;if('speechSynthesis'in window)speechSynthesis.cancel();}
 function shuffle(rows){const a=[...rows];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
 function valid(s,pack){return s&&Array.isArray(s.words)&&s.words.length===2&&new Set(s.words).size===2&&s.words.every(id=>pack.words.includes(id))&&Number.isInteger(s.step)&&s.step>=0&&s.step<=9&&Array.isArray(s.choices)&&s.choices.length===3&&s.choices.every((ids,i)=>Array.isArray(ids)&&ids.length===3&&new Set(ids).size===3&&ids.includes(s.words[i===1?1:0])&&ids.every(id=>pack.words.includes(id)));}
 function read(){let raw;try{raw=JSON.parse(localStorage.getItem(key)||'null');}catch{}const next=fresh();if(raw?.version!==1)return next;
  for(const word of content.words)if(Number.isInteger(raw.counts?.[word.id])&&raw.counts[word.id]>=0)next.counts[word.id]=Math.min(1000000,raw.counts[word.id]);
  next.completed=Number.isInteger(raw.completed)?Math.max(0,Math.min(10000,raw.completed)):0;
  for(const pack of content.packs){const s=raw.sessions?.[pack.id];if(!valid(s,pack))continue;const word=content.words.find(w=>w.id===s.words[s.step===8?0:Math.min(1,Math.floor(s.step/4))]);next.sessions[pack.id]={words:[...s.words],choices:s.choices.map(ids=>[...ids]),step:s.step,hint:Number.isInteger(s.hint)?Math.max(0,Math.min(2,s.hint)):0,errors:Number.isInteger(s.errors)?Math.max(0,Math.min(1000,s.errors)):0,picks:Array.isArray(s.picks)&&s.picks.length<=word.id.length&&new Set(s.picks).size===s.picks.length&&s.picks.every(i=>Number.isInteger(i)&&i>=0&&i<word.id.length)?[...s.picks]:[],draft:typeof s.draft==='string'&&/^[a-zA-Z]{0,30}$/.test(s.draft)?s.draft:''};}return next;
 }
 function save(next){try{localStorage.setItem(key,JSON.stringify(next));state=next;return true;}catch{status.textContent='Il browser non ha confermato il salvataggio. L’attività non avanza: libera spazio e riprova. Il ripasso illustrato resta disponibile.';return false;}}
 async function enter(){stop();revision.hidden=true;panel.hidden=false;open.setAttribute('aria-pressed','true');back.setAttribute('aria-pressed','false');panel.querySelector('h2').focus();if(loading)return;loading=true;status.textContent='Preparo le parole scaricate…';
  try{if(!content){const r=await fetch('training.json',{credentials:'omit'});if(!r.ok)throw Error();const d=await r.json();content={words:d.foundationWords||d.words,packs:d.wordPacks||[{id:'first',title:'Prime parole',icon:'🌱',words:d.words.map(w=>w.id)}]};}state=read();if(!panel.hidden)intro();}
  catch{status.textContent='Parole e spelling non sono ancora scaricati. Apri WordyLand con Internet almeno una volta e attendi che il ripasso sia pronto.';host.innerHTML='<button type="button" id="offlineFoundationRetry">Riprova</button>';host.querySelector('button').onclick=enter;}
  finally{loading=false;}
 }
 function intro(){stop();current=null;locked=false;status.textContent='Scegli un argomento: due parole alla volta, senza timer, monete o voti. Percorsi completati qui: '+state.completed+'.';host.innerHTML='<div class="offlinePackGrid">'+content.packs.map(p=>'<button type="button" data-offline-pack="'+esc(p.id)+'">'+esc(p.icon)+' '+esc(p.title)+'<small>'+((state.sessions[p.id]?.step??9)<9?'Riprendi · '+state.sessions[p.id].step+' / 9':'Due parole e una frase')+'</small></button>').join('')+'</div><p>I nomi delle lettere italiano/inglese restano nel percorso online. Qui puoi comporre e scrivere le parole, ascoltando la parola intera se la voce locale è disponibile.</p>';host.querySelectorAll('[data-offline-pack]').forEach(b=>b.onclick=()=>start(b.dataset.offlinePack));}
 function start(id){const pack=content.packs.find(p=>p.id===id);if(!pack)return;const next=clone();if(!next.sessions[id]||next.sessions[id].step===9){const ids=[...pack.words].sort((a,b)=>(next.counts[a]||0)-(next.counts[b]||0)).slice(0,2),options=id=>shuffle([id,...pack.words.filter(w=>w!==id).slice(0,2)]);next.sessions[id]={words:ids,choices:[options(ids[0]),options(ids[1]),options(ids[0])],step:0,hint:0,errors:0,picks:[],draft:''};if(!save(next))return;}current=id;draw();}
 function question(){const s=state.sessions[current],index=s.step===8?0:Math.floor(s.step/4);return {s,word:content.words.find(w=>w.id===s.words[index]),mode:s.step===8?'phrase':['model','recognize','build','recall'][s.step%4],choices:s.choices[s.step===8?2:index]};}
 function draw(){stop();locked=false;const s=state.sessions[current];if(s.step===9){host.innerHTML='<div class="offlineDone"><strong>🌟 Hai esplorato due parole!</strong><p>Puoi fare una pausa o scegliere un altro argomento. Questo passo è salvato solo qui.</p><button id="offlineFoundationAgain" type="button">Scegli un argomento</button></div>';status.textContent='Sessione conclusa e salvata in questo browser.';host.querySelector('button').onclick=intro;return;}
  const q=question(),w=q.word;status.textContent=s.step+' / 9 attività confermate in questo browser.';
  host.innerHTML='<div class="offlineSessionBar"><b>'+esc(content.packs.find(p=>p.id===current).title)+'</b><button type="button" id="offlineFoundationPause">⏸ Pausa</button></div><h3 tabindex="-1">'+({model:'Guarda la parola',recognize:'Leggi e cerca il significato',build:'Componi la parola',recall:'Scrivi la parola',phrase:'Una piccola frase'}[q.mode])+'</h3><div class="offlinePicture" aria-hidden="true">'+esc(w.emoji)+'</div><p class="offlineMeaning">'+esc(w.meaning)+'</p><button type="button" id="offlineWordAudio">🔊 Ascolta la parola</button><p id="offlineWordVoice">'+(selectedVoice()?'Voce locale disponibile: puoi riascoltare senza fretta.':'Voce locale non disponibile: puoi leggere e continuare. Non è una prova di ascolto.')+'</p><div id="offlineWordExercise"></div><div id="offlineWordHintModel"></div><button type="button" id="offlineWordHint">💡 Mostrami un aiuto</button><div id="offlineWordFeedback" role="status" aria-live="polite"></div><button type="button" id="offlineWordNext" hidden>Continua →</button>';
  const exercise=host.querySelector('#offlineWordExercise');
  if(q.mode==='model'){exercise.innerHTML='<p class="offlineBigWord">'+esc(w.id)+'</p><button type="button" id="offlineWordModel">Continua con calma</button>';exercise.querySelector('button').onclick=()=>submit(w.id);}
  else if(['recognize','phrase'].includes(q.mode)){exercise.innerHTML=(q.mode==='recognize'?'<p class="offlineBigWord">'+esc(w.id)+'</p>':'<p class="offlineBigWord">'+esc(w.gap)+'</p><p>Completa: '+esc(w.phraseMeaning)+'</p>')+'<div class="offlineOptions">'+q.choices.map(id=>{const row=content.words.find(w=>w.id===id);return '<button type="button" data-offline-word="'+id+'">'+esc(q.mode==='phrase'?id:row.meaning)+'</button>';}).join('')+'</div>';exercise.querySelectorAll('[data-offline-word]').forEach(b=>b.onclick=()=>submit(b.dataset.offlineWord));}
  else if(q.mode==='build'){exercise.innerHTML='<p class="offlineBigWord">'+esc(w.id)+'</p><div id="offlineWordSlots" role="group" aria-label="La parola composta"></div><div id="offlineWordTiles" role="group" aria-label="Lettere disponibili"></div><p id="offlineWordTileCount" role="status"></p><button type="button" id="offlineWordBuild">Controlla</button>';const tiles=shuffle([...w.id].map((char,id)=>({char,id})));exercise.querySelector('#offlineWordTiles').innerHTML=tiles.map(t=>'<button type="button" data-offline-tile="'+t.id+'" aria-label="Lettera '+t.char+'">'+t.char+'</button>').join('');
   const update=()=>{const picks=state.sessions[current].picks;exercise.querySelector('#offlineWordSlots').innerHTML=picks.map((id,i)=>'<button type="button" data-offline-slot="'+i+'" aria-label="Togli la lettera '+w.id[id]+'">'+w.id[id]+'</button>').join('');exercise.querySelectorAll('[data-offline-tile]').forEach(b=>b.disabled=picks.includes(Number(b.dataset.offlineTile)));exercise.querySelectorAll('[data-offline-slot]').forEach(b=>b.onclick=()=>{if(locked)return;const next=clone(),removed=next.sessions[current].picks.splice(Number(b.dataset.offlineSlot),1)[0];if(save(next)){update();exercise.querySelector('[data-offline-tile="'+removed+'"]').focus();}});exercise.querySelector('#offlineWordTileCount').textContent=picks.length+' di '+w.id.length+' lettere';};
   exercise.querySelectorAll('[data-offline-tile]').forEach(b=>b.onclick=()=>{if(locked)return;const next=clone(),picks=next.sessions[current].picks,id=Number(b.dataset.offlineTile);if(picks.includes(id))return;picks.push(id);if(save(next)){update();(exercise.querySelector('[data-offline-tile]:not(:disabled)')||exercise.querySelector('#offlineWordBuild')).focus();}});exercise.querySelector('#offlineWordBuild').onclick=()=>submit(state.sessions[current].picks.map(id=>w.id[id]).join(''));update();
  }else{exercise.innerHTML='<form id="offlineWordWrite"><label for="offlineWordAnswer">Scrivi in inglese, oppure chiedi un aiuto</label><input id="offlineWordAnswer" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="30" required><button type="submit">Controlla</button></form>';const input=exercise.querySelector('input');input.value=s.draft;input.oninput=()=>{const next=clone();next.sessions[current].draft=input.value.replace(/[^a-zA-Z]/g,'').slice(0,30);save(next);};exercise.querySelector('form').onsubmit=e=>{e.preventDefault();submit(input.value);};}
  host.querySelector('#offlineFoundationPause').onclick=intro;host.querySelector('#offlineWordNext').onclick=draw;host.querySelector('#offlineWordHint').onclick=()=>{if(locked)return;const next=clone();next.sessions[current].hint=Math.min(2,next.sessions[current].hint+1);if(save(next))showHint();};showHint();
  const audio=host.querySelector('#offlineWordAudio');audio.disabled=!selectedVoice();audio.onclick=()=>{if(locked)return;stop();const voice=selectedVoice();if(!voice)return;const generation=speechGeneration,u=new SpeechSynthesisUtterance(w.id);u.lang=voice.lang;u.voice=voice;u.rate=.8;u.onerror=()=>{if(generation===speechGeneration&&host.querySelector('#offlineWordVoice'))host.querySelector('#offlineWordVoice').textContent='Audio non disponibile: continua leggendo. Non viene registrata una prova di ascolto.';};speechSynthesis.speak(u);};host.querySelector('h3').focus();
 }
 function showHint(){const level=state.sessions[current].hint,q=question(),box=host.querySelector('#offlineWordHintModel');if(box)box.innerHTML=level?'<p>Guardiamo insieme.</p><p class="offlineBigWord">'+esc(level===1?q.word.id[0]+'…':q.word.id)+'</p>':'';}
 function submit(value){if(locked)return;const q=question(),next=clone(),s=next.sessions[current],correct=q.mode==='model'||String(value).trim().toLowerCase()===q.word.id,feedback=host.querySelector('#offlineWordFeedback');
  if(!correct){s.errors=Math.min(1000,s.errors+1);if(save(next)){window.wordylandLearning.show(feedback,false,{expected:q.word.id,word:q.word.id,translation:q.word.meaning,answer:value});if(s.errors>=2){const helped=clone();helped.sessions[current].hint=2;if(save(helped))showHint();}}return;}
  s.step++;s.hint=0;s.errors=0;s.picks=[];s.draft='';next.counts[q.word.id]=Math.min(1000000,(next.counts[q.word.id]||0)+1);if(s.step===9)next.completed=Math.min(10000,next.completed+1);if(!save(next))return;locked=true;stop();host.querySelectorAll('#offlineWordExercise button,#offlineWordExercise input,#offlineWordHint,#offlineWordAudio').forEach(b=>b.disabled=true);window.wordylandLearning.show(feedback,true,{expected:q.word.id,word:q.word.id,translation:q.word.meaning});const button=host.querySelector('#offlineWordNext');button.hidden=false;button.focus();
 }
 open.onclick=enter;back.onclick=()=>{stop();panel.hidden=true;revision.hidden=false;open.setAttribute('aria-pressed','false');back.setAttribute('aria-pressed','true');document.querySelector('#offlineTopic').focus();};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});window.addEventListener('pagehide',stop);
})();
